        fDistance = range,
        fStartRadius = 165,
        fEndRadius = 215,
        Source = caster,
        vVelocity = Vector(dir.x * 1350, dir.y * 1350, 0),
        iUnitTargetTeam = 2,
        iUnitTargetType = 1 + 18,
        iUnitTargetFlags = 0
    })
    if self:GetLevel() >= 3 then
        do
            local step = 1
            while step <= 3 do
                local wakePos = Vector(origin.x + dir.x * (range * step * 0.28), origin.y + dir.y * (range * step * 0.28), origin.z)
                CreateModifierThinker(
                    caster,
                    self,
                    "modifier_evo_slark_int_w_wake",
