    end
    local baseDmg = self:GetSpecialValueFor("base_damage")
    local intPct = self:GetSpecialValueFor("int_pct") / 100
    local intVal = caster:IsRealHero() and caster:GetIntellect(false) or 0
    ApplyDamage({
        victim = target,
        attacker = caster,
        ability = self,
        damage = baseDmg + intVal * intPct,
        damage_type = 2
    })
    target:AddNewModifier(caster, self, "modifier_evo_slark_int_w_slow", {duration = 3})
